ee:message.ee:set-payload:
%dw 2.0
output application/json
var rawText = (payload as String default "")
var parsedPayload = if (isEmpty(trim(rawText))) {} else (read(rawText, "application/json") default {})
---
parsedPayload

ee:variables.ee:set-variable:
%dw 2.0
output application/json
var rawText = (payload as String default "")
var parsedPayload = if (isEmpty(trim(rawText))) {} else (read(rawText, "application/json") default {})
---
parsedPayload

%dw 2.0
output application/java
var rawText = (payload as String default "")
var parsedPayload = if (isEmpty(trim(rawText))) {} else (read(rawText, "application/json") default {})
---
parsedPayload.correlationId default uuid()
